import { readFileSync, writeFileSync } from 'node:fs';
const read=(path)=>readFileSync(path,'utf8');
const write=(path,value)=>writeFileSync(path,value);
function replaceOne(path,before,after){const value=read(path);if(!value.includes(before))throw new Error(`Missing Terraform target anchor: ${path}`);if(value.indexOf(before)!==value.lastIndexOf(before))throw new Error(`Non-unique Terraform target anchor: ${path}`);write(path,value.replace(before,after));}

write('infrastructure/terraform/modules/environment/api_identity_platform_iam.tf',`# Identity Platform/Firebase IAM is intentionally not part of the unified target runtime.\n# Appwrite is the authentication/session authority for launch environments.\n`);
write('infrastructure/terraform/modules/environment/app_check.tf',`variable "app_check_recaptcha_enterprise_site_key" {\n  description = "Deprecated Firebase compatibility input. Unified Appwrite launch environments must leave this unset."\n  type        = string\n  default     = null\n  nullable    = true\n  validation {\n    condition     = var.app_check_recaptcha_enterprise_site_key == null\n    error_message = "Firebase App Check is not part of the unified Appwrite target architecture."\n  }\n}\n\nvariable "app_check_enforcement_mode" {\n  description = "Deprecated Firebase compatibility input. Must remain UNENFORCED."\n  type        = string\n  default     = "UNENFORCED"\n  validation {\n    condition     = var.app_check_enforcement_mode == "UNENFORCED"\n    error_message = "Firebase App Check cannot be enabled in the unified Appwrite target architecture."\n  }\n}\n\nvariable "require_api_app_check" {\n  description = "Deprecated Firebase compatibility input. Appwrite auth replaces Firebase App Check for this runtime."\n  type        = bool\n  default     = false\n  validation {\n    condition     = var.require_api_app_check == false\n    error_message = "Firebase App Check cannot be required by the unified Appwrite API runtime."\n  }\n}\n\noutput "app_check" {\n  value = {\n    enforcement_mode        = "DISABLED_APPWRITE_TARGET"\n    web_provider_configured = false\n  }\n}\n`);

const main='infrastructure/terraform/modules/environment/main.tf';
replaceOne(main,`  services = toset([\n    "aiplatform.googleapis.com",`,`  services = toset([\n    "aiplatform.googleapis.com",`);
replaceOne(main,`    "firebase.googleapis.com",\n    "firebasehosting.googleapis.com",\n    "firestore.googleapis.com",\n    "iam.googleapis.com",\n    "identitytoolkit.googleapis.com",`,`    "iam.googleapis.com",`);
replaceOne(main,`    "storage.googleapis.com",\n  ])`,`    "storage.googleapis.com",\n  ])\n  core_services = {\n    api = {\n      service_account = google_service_account.runtime["api"].email\n      ingress         = "INGRESS_TRAFFIC_ALL"\n      cpu             = "1"\n      memory          = "1Gi"\n      max_instances   = local.production ? 30 : 5\n    }\n    "pdf-worker" = {\n      service_account = google_service_account.runtime["pdf_worker"].email\n      ingress         = "INGRESS_TRAFFIC_INTERNAL_ONLY"\n      cpu             = "2"\n      memory          = "2Gi"\n      max_instances   = local.production ? 20 : 5\n    }\n  }`);
replaceOne(main,`resource "google_storage_bucket" "assets" {`,`resource "google_pubsub_topic" "pdf" {\n  name    = "pdf-generation-requests"\n  project = var.project_id\n  labels  = local.labels\n\n  message_storage_policy {\n    allowed_persistence_regions = [var.region]\n    enforce_in_transit          = true\n  }\n}\n\nresource "google_storage_bucket" "assets" {`);
replaceOne(main,`resource "google_billing_budget" "monthly" {`,`resource "google_cloud_run_v2_service" "service" {\n  for_each            = local.core_services\n  project             = var.project_id\n  location            = var.region\n  name                = each.key\n  ingress             = each.value.ingress\n  deletion_protection = local.production\n  labels              = local.labels\n\n  template {\n    service_account = each.value.service_account\n    scaling {\n      min_instance_count = 0\n      max_instance_count = each.value.max_instances\n    }\n    containers {\n      image = "us-docker.pkg.dev/cloudrun/container/hello"\n      env {\n        name  = "APP_ENV"\n        value = var.environment\n      }\n      env {\n        name  = "NODE_ENV"\n        value = local.production ? "production" : "development"\n      }\n      env {\n        name  = "GOOGLE_CLOUD_PROJECT"\n        value = var.project_id\n      }\n      resources {\n        limits = { cpu = each.value.cpu, memory = each.value.memory }\n      }\n    }\n  }\n  lifecycle {\n    ignore_changes = [template[0].containers[0].image, template[0].containers[0].env]\n  }\n  depends_on = [google_project_service.required]\n}\n\nresource "google_cloud_run_v2_service_iam_member" "api_public" {\n  count    = var.api_allow_unauthenticated ? 1 : 0\n  project  = var.project_id\n  location = var.region\n  name     = google_cloud_run_v2_service.service["api"].name\n  role     = "roles/run.invoker"\n  member   = "allUsers"\n}\n\nresource "google_billing_budget" "monthly" {`);
replaceOne(main,`output "report_bucket" { value = google_storage_bucket.reports.name }`,`output "report_bucket" { value = google_storage_bucket.reports.name }\noutput "api_url" { value = google_cloud_run_v2_service.service["api"].uri }\noutput "pdf_worker_url" { value = google_cloud_run_v2_service.service["pdf-worker"].uri }`);

const pdf='infrastructure/terraform/modules/environment/pdf_delivery.tf';
replaceOne(pdf,`resource "google_storage_bucket_iam_member" "pdf_worker_upload_viewer" {\n  bucket = google_storage_bucket.uploads.name\n  role   = "roles/storage.objectViewer"\n  member = "serviceAccount:\${google_service_account.runtime["pdf_worker"].email}"\n}\n\n`,'');

const tenant='infrastructure/terraform/modules/environment/tenant_delivery.tf';
replaceOne(tenant,`resource "google_project_iam_member" "notification_worker_datastore" {\n  project = var.project_id\n  role    = "roles/datastore.user"\n  member  = "serviceAccount:\${google_service_account.notification_worker.email}"\n}\n\n`,'');
replaceOne(tenant,`      env {\n        name  = "FIRESTORE_DATABASE_ID"\n        value = var.firestore_database_id\n      }\n      env {\n        name  = "WEB_APP_BASE_URL"\n        value = "https://\${google_firebase_hosting_site.web.site_id}.web.app"\n      }\n`,'');
replaceOne(tenant,`    google_project_service.required,\n    google_project_iam_member.notification_worker_datastore,\n    google_project_iam_member.notification_worker_secrets,`,`    google_project_service.required,\n    google_project_iam_member.notification_worker_secrets,`);

const dashboard='infrastructure/terraform/modules/environment/dashboard_delivery.tf';
replaceOne(dashboard,`resource "google_project_iam_member" "dashboard_worker_datastore" {\n  project = var.project_id\n  role    = "roles/datastore.user"\n  member  = "serviceAccount:\${google_service_account.dashboard_worker.email}"\n}\n\n`,'');
replaceOne(dashboard,`      env {\n        name  = "FIRESTORE_DATABASE_ID"\n        value = var.firestore_database_id\n      }\n`,'');
replaceOne(dashboard,`  depends_on = [\n    google_project_service.required,\n    google_project_iam_member.dashboard_worker_datastore,\n  ]`,`  depends_on = [google_project_service.required]`);

const enhancement='infrastructure/terraform/modules/environment/platform_enhancement_delivery.tf';
replaceOne(enhancement,`resource "google_project_iam_member" "enhancement_worker_datastore" {\n  for_each = local.enhancement_workers\n  project  = var.project_id\n  role     = "roles/datastore.user"\n  member   = "serviceAccount:\${google_service_account.enhancement_worker[each.key].email}"\n}\n\n`,'');
replaceOne(enhancement,`      env {\n        name  = "FIRESTORE_DATABASE_ID"\n        value = var.firestore_database_id\n      }\n`,'');
replaceOne(enhancement,`  depends_on = [\n    google_project_service.required,\n    google_project_iam_member.enhancement_worker_datastore,\n  ]`,`  depends_on = [google_project_service.required]`);

console.log('Removed Firebase target resources and restored Appwrite-target Google Cloud Run core infrastructure.');
